mapper.select:
SELECT b.id,b.provider,b.provider_instance_id AS providerInstanceId,b.external_user_id AS externalUserId,
  b.principal_id AS principalId,p.principal_code AS principalCode,p.name AS principalName,b.status,
  b.created_by AS createdBy,b.created_time AS createdTime,b.updated_by AS updatedBy,b.updated_time AS updatedTime,b.reason
FROM t_external_identity_binding b JOIN t_principal p ON p.id=b.principal_id
AND b.provider=#{provider}
  AND b.provider_instance_id=#{providerInstanceId}
  AND b.external_user_id=#{externalUserId}
ORDER BY b.updated_time DESC,b.id DESC

mapper.update:
UPDATE t_external_identity_binding SET principal_id=#{principalId},status='ACTIVE',
  revoked_by=NULL,revoked_time=NULL,updated_by=#{operatorId},updated_time=CURRENT_TIMESTAMP,reason=#{reason}
  WHERE id=#{id} AND status='REVOKED'

mapper.select:
SELECT * FROM t_api_call_audit

    key_id=#{keyId}

  ORDER BY created_time DESC, id DESC LIMIT #{limit}

SELECT * FROM t_api_call_audit

    token_jti=#{jti}
    AND key_id=#{keyId}

  ORDER BY created_time DESC,id DESC LIMIT #{limit}
